CREATE TABLE IF NOT EXISTS public.gm_security_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_code text NOT NULL,severity text NOT NULL CHECK (severity IN ('medium','high','critical')),fingerprint text NOT NULL,title text NOT NULL,description text NOT NULL,event_count integer NOT NULL DEFAULT 0,window_started_at timestamptz NOT NULL DEFAULT now(),last_event_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,resolved_by uuid REFERENCES public.usuarios(id),metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE UNIQUE INDEX IF NOT EXISTS gm_security_alerts_active_fingerprint_idx ON public.gm_security_alerts(fingerprint) WHERE resolved_at IS NULL;
CREATE INDEX IF NOT EXISTS gm_security_alerts_open_idx ON public.gm_security_alerts(resolved_at,severity,last_event_at DESC);
ALTER TABLE public.gm_security_alerts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.gm_security_alerts FORCE ROW LEVEL SECURITY; REVOKE ALL ON public.gm_security_alerts FROM PUBLIC,anon,authenticated; GRANT SELECT,INSERT,UPDATE ON public.gm_security_alerts TO service_role;
ALTER TABLE public.governance_export_requests ADD COLUMN IF NOT EXISTS classificacao text NOT NULL DEFAULT 'confidencial'; ALTER TABLE public.governance_export_requests ADD COLUMN IF NOT EXISTS finalidade text; ALTER TABLE public.governance_export_requests ADD COLUMN IF NOT EXISTS justificativa text; ALTER TABLE public.governance_export_requests ADD COLUMN IF NOT EXISTS auditoria_em timestamptz;
CREATE INDEX IF NOT EXISTS governance_export_confidential_idx ON public.governance_export_requests(classificacao,solicitado_em DESC);
CREATE OR REPLACE FUNCTION public.gm_evaluate_security_alert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE key_value text; total_count integer; severity_value text; rule_value text; title_value text; description_value text; since_ts timestamptz;
BEGIN
 IF NEW.event_type='failed_login' THEN since_ts:=now()-interval '15 minutes'; total_count:=(SELECT count(*) FROM public.gm_auth_security_events WHERE event_type='failed_login' AND occurred_at>=since_ts AND attempt_key_hash=NEW.attempt_key_hash); IF total_count>=5 THEN rule_value:='excessive_failed_logins'; severity_value:=CASE WHEN total_count>=10 THEN 'critical' ELSE 'high' END; title_value:='Tentativas excessivas de login'; description_value:=format('%s tentativas malsucedidas para o mesmo identificador protegido na última janela.',total_count); END IF;
 ELSIF NEW.event_type='blocked_login' THEN since_ts:=now()-interval '30 minutes'; total_count:=(SELECT count(*) FROM public.gm_auth_security_events WHERE event_type='blocked_login' AND occurred_at>=since_ts AND attempt_key_hash=NEW.attempt_key_hash); IF total_count>=2 THEN rule_value:='repeated_login_blocks'; severity_value:='critical'; title_value:='Bloqueios de login repetidos'; description_value:=format('%s bloqueios de segurança registrados na última janela.',total_count); END IF; END IF;
 IF rule_value IS NOT NULL THEN key_value:=rule_value||':'||coalesce(NEW.attempt_key_hash,'global'); INSERT INTO public.gm_security_alerts(rule_code,severity,fingerprint,title,description,event_count,window_started_at,last_event_at,metadata) VALUES(rule_value,severity_value,key_value,title_value,description_value,total_count,since_ts,NEW.occurred_at,jsonb_build_object('event_type',NEW.event_type)) ON CONFLICT (fingerprint) WHERE resolved_at IS NULL DO UPDATE SET severity=EXCLUDED.severity,description=EXCLUDED.description,event_count=EXCLUDED.event_count,last_event_at=EXCLUDED.last_event_at,metadata=EXCLUDED.metadata; END IF; RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS gm_security_alert_evaluate ON public.gm_auth_security_events; CREATE TRIGGER gm_security_alert_evaluate AFTER INSERT ON public.gm_auth_security_events FOR EACH ROW EXECUTE FUNCTION public.gm_evaluate_security_alert(); REVOKE ALL ON FUNCTION public.gm_evaluate_security_alert() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.gm_evaluate_security_alert() TO service_role;
CREATE OR REPLACE FUNCTION public.gm_security_alerts() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE actor_id uuid; result jsonb; BEGIN SELECT u.id INTO actor_id FROM public.usuarios u WHERE u.auth_user_id=auth.uid() AND u.perfil='administrador' AND u.status='ativo' AND u.deleted_at IS NULL; IF actor_id IS NULL THEN RAISE EXCEPTION 'admin_required'; END IF; SELECT jsonb_build_object('alerts',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.last_event_at DESC),'[]'::jsonb)) INTO result FROM (SELECT id,rule_code,severity,title,description,event_count,window_started_at,last_event_at,metadata FROM public.gm_security_alerts WHERE resolved_at IS NULL ORDER BY last_event_at DESC LIMIT 50) x; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.gm_security_alerts() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.gm_security_alerts() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.gm_audit_confidential_export() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.logs_auditoria(usuario_id,acao,entidade,entidade_id,dados_novos) VALUES(NEW.solicitado_por,'request_confidential_export','governance_export_requests',NEW.id,jsonb_build_object('classificacao',coalesce(NEW.classificacao,NEW.escopo->>'classificacao','confidencial'),'finalidade',left(coalesce(NEW.finalidade,NEW.escopo->>'finalidade',''),240),'justificativa',left(coalesce(NEW.justificativa,NEW.escopo->>'justificativa',''),500),'escopo',NEW.escopo,'status',NEW.status)); ELSIF TG_OP='UPDATE' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.objeto_path IS DISTINCT FROM OLD.objeto_path) THEN INSERT INTO public.logs_auditoria(usuario_id,acao,entidade,entidade_id,dados_anteriores,dados_novos) VALUES(NEW.solicitado_por,'export_status_change','governance_export_requests',NEW.id,jsonb_build_object('status',OLD.status,'objeto_disponivel',OLD.objeto_path IS NOT NULL),jsonb_build_object('status',NEW.status,'objeto_disponivel',NEW.objeto_path IS NOT NULL,'concluido_em',NEW.concluido_em,'expira_em',NEW.expira_em,'erro_codigo',NEW.erro_codigo)); END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS governance_export_audit ON public.governance_export_requests; CREATE TRIGGER governance_export_audit AFTER INSERT OR UPDATE OF status,objeto_path ON public.governance_export_requests FOR EACH ROW EXECUTE FUNCTION public.gm_audit_confidential_export(); REVOKE ALL ON FUNCTION public.gm_audit_confidential_export() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.gm_audit_confidential_export() TO service_role;
